        int profit = 0;
        int buy = INT_MAX;
        for (int i = 0; i < prices.size(); i++) {
            buy = min(prices[i], buy);
            profit += (prices[i] - buy);
            buy = max(buy,prices[i]);
        }
        return profit;
    }
};

